//! Accès bas niveau au presse-papiers macOS (NSPasteboard) :
//! compteur de changements et types déclarés, sans lire le contenu.

/// Types posés par les gestionnaires de mots de passe et les apps qui signalent
/// un contenu confidentiel ou temporaire (convention http://nspasteboard.org).
const IGNORED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
];

/// Vrai si le contenu ne doit pas être enregistré (mot de passe, contenu temporaire…).
pub fn should_ignore(types: &[String]) -> bool {
    types
        .iter()
        .any(|t| IGNORED_TYPES.iter().any(|ignored| t == ignored))
}

#[cfg(target_os = "macos")]
mod imp {
    use objc2::rc::autoreleasepool;
    use objc2::runtime::AnyObject;
    use objc2::{class, msg_send};
    use std::ffi::{c_char, CStr};

    fn general() -> *mut AnyObject {
        unsafe { msg_send![class!(NSPasteboard), generalPasteboard] }
    }

    /// Compteur incrémenté par macOS à chaque nouvelle copie, quelle que soit l'app.
    pub fn change_count() -> Option<isize> {
        autoreleasepool(|_| {
            let pb = general();
            if pb.is_null() {
                return None;
            }
            let count: isize = unsafe { msg_send![pb, changeCount] };
            Some(count)
        })
    }

    /// Identifiants des types présents (UTI), sans lire les données.
    pub fn types() -> Vec<String> {
        autoreleasepool(|_| unsafe {
            let pb = general();
            if pb.is_null() {
                return Vec::new();
            }
            let array: *mut AnyObject = msg_send![pb, types];
            if array.is_null() {
                return Vec::new();
            }
            let n: usize = msg_send![array, count];
            (0..n)
                .filter_map(|i| {
                    let s: *mut AnyObject = msg_send![array, objectAtIndex: i];
                    if s.is_null() {
                        return None;
                    }
                    let c: *const c_char = msg_send![s, UTF8String];
                    (!c.is_null()).then(|| CStr::from_ptr(c).to_string_lossy().into_owned())
                })
                .collect()
        })
    }
}

#[cfg(not(target_os = "macos"))]
mod imp {
    pub fn change_count() -> Option<isize> {
        None
    }
    pub fn types() -> Vec<String> {
        Vec::new()
    }
}

pub use imp::{change_count, types};

#[cfg(test)]
mod tests {
    use super::*;

    fn v(items: &[&str]) -> Vec<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn ignores_password_manager_types() {
        assert!(should_ignore(&v(&["public.utf8-plain-text", "org.nspasteboard.ConcealedType"])));
        assert!(should_ignore(&v(&["com.agilebits.onepassword"])));
        assert!(should_ignore(&v(&["org.nspasteboard.TransientType"])));
    }

    #[test]
    fn keeps_regular_text() {
        assert!(!should_ignore(&v(&["public.utf8-plain-text", "NSStringPboardType"])));
        assert!(!should_ignore(&[]));
    }
}
